import React from 'react';
import {
    Paper,
    Typography,
    Box,
    TextField,
    Button,
    IconButton,
    Checkbox,
    List,
    ListItem,
    ListItemButton,
    ListItemIcon,
    ListItemText,
    Divider,
    Avatar,
    InputAdornment,
    CircularProgress
} from '@mui/material';
import { Search as SearchIcon, Add as AddIcon, Delete as DeleteIcon } from '@mui/icons-material';

const PlatformCard = ({ platform, data, onAdd, onSearch, onDelete, onSelect, onSelectAll, loading }) => {
    const [selected, setSelected] = React.useState([]);
    const [searchQuery, setSearchQuery] = React.useState('');
    const [isSearching, setIsSearching] = React.useState(false);
    const debounceTimer = React.useRef(null);

    const handleSearchChange = (e) => {
        const value = e.target.value;
        setSearchQuery(value); // This is async - won't update immediately

        // Log the current input value, not the state
        console.log('Current input value:', value);
        console.log('Platform ID:', platform.id);

        // Clear previous timer
        if (debounceTimer.current) {
            clearTimeout(debounceTimer.current);
        }

        if (value.trim()) {
            setIsSearching(true);
            debounceTimer.current = setTimeout(() => {
                console.log('Debounced search triggered with:', {
                    platformId: platform.id,
                    username: value
                });
                if (onSearch) {
                    onSearch(platform.id, value);
                }
            }, 500);
        } else {
            setIsSearching(false);
            if (onSearch) {
                onSearch(platform.id, value);
            }
        }
    };
    React.useEffect(
        () => () => {
            if (debounceTimer.current) {
                clearTimeout(debounceTimer.current);
            }
        },
        []
    );

    const handleSelectAllClick = (event) => {
        if (event.target.checked) {
            const newSelected = data.map((item) => item.id);
            setSelected(newSelected);
            if (onSelectAll) onSelectAll(newSelected);
        } else {
            setSelected([]);
            if (onSelectAll) onSelectAll([]);
        }
    };

    const handleSelectClick = (id) => {
        const selectedIndex = selected.indexOf(id);
        let newSelected = [];

        if (selectedIndex === -1) {
            newSelected = [...selected, id];
        } else {
            newSelected = selected.filter((item) => item !== id);
        }

        setSelected(newSelected);
        if (onSelect) onSelect(newSelected);
    };

    const isSelected = (id) => selected.indexOf(id) !== -1;

    return (
        <Paper
            elevation={0}
            sx={{
                p: 2,
                border: '1px solid #eaeaea',
                borderRadius: '8px',
                backgroundColor: '#ffffff',
                transition: 'all 0.2s ease',
                '&:hover': {
                    transform: 'translateY(-2px)',
                    boxShadow: '0 4px 8px rgba(0,0,0,0.05)',
                    borderColor: '#4caf50'
                }
            }}
        >
            <Typography
                variant="subtitle1"
                sx={{
                    display: 'flex',
                    alignItems: 'center',
                    mb: 2,
                    fontWeight: '600',
                    color: '#444'
                }}
            >
                {platform.icon}
                <span style={{ marginLeft: 8 }}>{platform.text.replace('Add ', '')}</span>
            </Typography>

            <Box sx={{ display: 'flex', gap: 1, mb: 2 }}>
                <TextField
                    placeholder="Search profiles..."
                    size="small"
                    fullWidth
                    value={searchQuery}
                    onChange={handleSearchChange}
                    disabled={loading}
                    sx={{
                        '& .MuiOutlinedInput-root': {
                            '& fieldset': { borderColor: '#e0e0e0' },
                            '&:hover fieldset': { borderColor: '#4caf50' }
                        }
                    }}
                    InputProps={{
                        startAdornment: (
                            <InputAdornment position="start">
                                {loading ? <CircularProgress size={20} /> : <SearchIcon fontSize="small" sx={{ color: '#9e9e9e' }} />}
                            </InputAdornment>
                        )
                    }}
                />
                <IconButton
                    size="small"
                    onClick={() => onDelete && onDelete(selected)}
                    sx={{
                        color: '#9e9e9e',
                        '&:hover': { color: '#f44336' }
                    }}
                >
                    <DeleteIcon />
                </IconButton>
            </Box>

            {data && data.length > 0 ? (
                <>
                    <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                        <Checkbox
                            indeterminate={selected.length > 0 && selected.length < data.length}
                            checked={data.length > 0 && selected.length === data.length}
                            onChange={handleSelectAllClick}
                            size="small"
                        />
                        <Typography variant="body2" sx={{ color: 'text.secondary' }}>
                            Select all
                        </Typography>
                    </Box>

                    <List
                        dense
                        sx={{
                            maxHeight: 300,
                            overflow: 'auto',
                            border: '1px solid #f0f0f0',
                            borderRadius: '6px',
                            py: 0
                        }}
                    >
                        {data.map((row) => {
                            const isItemSelected = isSelected(row.id);
                            return (
                                <React.Fragment key={row.id}>
                                    <ListItem
                                        secondaryAction={
                                            <Checkbox edge="end" checked={isItemSelected} onChange={() => handleSelectClick(row.id)} />
                                        }
                                        disablePadding
                                    >
                                        <ListItemButton onClick={() => handleSelectClick(row.id)}>
                                            <ListItemIcon>
                                                <Avatar
                                                    sx={{
                                                        width: 32,
                                                        height: 32,
                                                        bgcolor: isItemSelected ? '#4caf50' : '#e0e0e0',
                                                        color: isItemSelected ? '#fff' : '#555'
                                                    }}
                                                >
                                                    {row.username.charAt(0).toUpperCase()}
                                                </Avatar>
                                            </ListItemIcon>
                                            <ListItemText
                                                primary={row.username}
                                                primaryTypographyProps={{
                                                    fontWeight: isItemSelected ? 600 : 'normal',
                                                    color: isItemSelected ? '#4caf50' : 'inherit'
                                                }}
                                            />
                                        </ListItemButton>
                                    </ListItem>
                                    <Divider component="li" sx={{ my: 0 }} />
                                </React.Fragment>
                            );
                        })}
                    </List>
                </>
            ) : (
                <Box
                    sx={{
                        display: 'flex',
                        justifyContent: 'center',
                        alignItems: 'center',
                        height: 200,
                        mb: 2,
                        backgroundColor: '#f8f9fa',
                        borderRadius: '6px',
                        border: '1px dashed #e0e0e0'
                    }}
                >
                    <img
                        src="https://socialhype.live/inc/themes/backend/Stackmin/Assets/img/empty2.png"
                        alt="placeholder"
                        style={{
                            maxHeight: '90%',
                            maxWidth: '90%',
                            opacity: 0.5
                        }}
                    />
                </Box>
            )}

            <Button
                fullWidth
                variant="outlined"
                startIcon={<AddIcon />}
                onClick={onAdd}
                sx={{
                    mt: 2,
                    textTransform: 'none',
                    borderColor: '#e0e0e0',
                    color: '#555',
                    '&:hover': {
                        borderColor: '#4caf50',
                        color: '#4caf50'
                    }
                }}
            >
                Add Platform
            </Button>
        </Paper>
    );
};

export default PlatformCard;
